window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-839bb8def956e293"]={"versions": [{"id": "FIG-839bb8def956e293", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des Empfangsablaufs (<code>sequence - reception</code>) einer E2E-geschützten I-PDU im AUTOSAR Classic Platform Schichtenmodell. Das Diagramm zeigt die Interaktion beim Empfang über PduR, Com, einen anwendungsspezifischen COM Callout zur E2E-Prüfung, die E2E-Bibliothek, die Rte und die Software-Komponente (SWC).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Instanzen und Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>«module» PduR</code> (PDU Router)\n</li><li><code>«module» Com</code> (AUTOSAR COM-Modul mit Schnittstellensymbol)\n</li><li><code>COM Callout IPDU_Protect_21</code> (Empfangs-Callout-Funktion)\n</li><li><code>«module» E2E</code> (E2E-Bibliothek)\n</li><li><code>«module» Rte</code> (Runtime Environment)\n</li><li><code>SWC</code> (Software Component)\n</li></ul>\n<p class=\"fig-p\">Aufgerufene Schnittstellen und Datenstrukturen:</p>\n<ul class=\"fig-list\"><li><code>COM_RxIndication()</code>\n</li><li><code>IPDU_Check_21(id, ipduData)</code>\n</li><li><code>E2E_P01Check(&amp;Settings, &amp;State, &amp;ipduData)</code>\n</li><li>Interne Variablen und Zustände: <code>State.NewDataAvailable</code>, <code>Settings</code>, <code>State</code>, <code>State.Status</code>, <code>E2E_P01STATUS_OK</code>, Rückgabewert <code>ret</code>\n</li><li>Signalebenen-Interaktionen: <code>Received signals</code>, <code>Received data elements</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>PduR</code> signalisiert den Empfang an <code>Com</code> via <code>COM_RxIndication()</code>.\n</li><li><code>Com</code> ruft den Callout <code>IPDU_Check_21(id, ipduData)</code> auf.\n</li><li>Im Callout erfolgt einmalig beim Hochlauf (<code>[One time at startup]</code>) die Initialisierung von Konfigurations- und Zustandsstrukturen (<code>Hardcoded initialization of config/state structures</code>).\n</li><li><code>State.NewDataAvailable</code> wird auf <code>TRUE</code> gesetzt.\n</li><li>Der Callout ruft <code>E2E_P01Check(&amp;Settings, &amp;State, &amp;ipduData)</code> im Modul <code>E2E</code> auf.\n</li><li><code>E2E</code> führt die Prüfalgorithmen aus (<code>Execute check algorithms</code>) und liefert <code>Updated State</code> zurück.\n</li><li>Der Callout ermittelt das Prüfergebnis über <code>ret = ((State.Status == E2E_P01STATUS_OK) || (State.Status == E2E_P01STATUS_OK))</code> und gibt <code>ret</code> an <code>Com</code> zurück.\n</li><li>Bei <code>ret == FALSE</code> bricht <code>Com</code> die Weiterverarbeitung der I-PDU ab (<code>[ret == FALSE]:exit processing of I-PDU</code>).\n</li><li>Bei erfolgreicher Validierung extrahiert <code>Com</code> die Signale aus I-PDU 21 unter Berücksichtigung erforderlicher Konvertierungen (z. B. Endianness) (<code>Create signals out of I-PDU 21, do necessary conversions e.g. endiannes</code>).\n</li><li><code>Com</code> übergibt <code>Received signals</code> an die <code>Rte</code>.\n</li><li><code>Rte</code> leitet <code>Received data elements</code> an die <code>SWC</code> weiter.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als Integrations- und Implementierungsbeispiel für den E2E-Schutz über COM-Callouts auf Empfängerseite (Profil 1). Die Prüfung der I-PDU erfolgt vor dem Signalentpacken im COM-Stack. Schlägt die E2E-Validierung fehl (<code>ret == FALSE</code>), verwirft das COM-Modul die PDU, sodass keine fehlerhaften oder korrumpierten Signale an Rte und SWC propagiert werden. Die boolesche Auswertung <code>State.Status == E2E_P01STATUS_OK</code> steuert den Kontrollfluss direkt.</p>"}, {"id": "FIG-33f42cfe9c466859", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des Empfangsablaufs (<code>sequence - reception</code>) einer E2E-geschützten I-PDU im AUTOSAR Classic Platform Schichtenmodell. Das Diagramm zeigt die Interaktion beim Empfang über PduR, Com, einen anwendungsspezifischen COM Callout zur E2E-Prüfung, die E2E-Bibliothek, die Rte und die Software-Komponente (SWC).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Instanzen und Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>«module» PduR</code> (PDU Router)\n</li><li><code>«module» Com</code> (AUTOSAR COM-Modul mit Schnittstellensymbol)\n</li><li><code>COM Callout IPDU_E2ECheck_21</code> (Empfangs-Callout-Funktion)\n</li><li><code>«module» E2E</code> (E2E-Bibliothek)\n</li><li><code>«module» Rte</code> (Runtime Environment)\n</li><li><code>SWC</code> (Software Component)\n</li></ul>\n<p class=\"fig-p\">Aufgerufene Schnittstellen und Datenstrukturen:</p>\n<ul class=\"fig-list\"><li><code>COM_RxIndication()</code>\n</li><li><code>IPDU_E2ECheck_21(RxPduId, IPduInfo)</code>\n</li><li><code>E2E_P01Check(&amp;Settings, &amp;State, IPduInfo-&gt;SduDataPtr)</code>\n</li><li>Interne Variablen und Zustände: <code>State.NewDataAvailable</code>, <code>Settings</code>, <code>State</code>, <code>State.Status</code>, <code>E2E_P01STATUS_OK</code>, Rückgabewert <code>ret</code>\n</li><li>Signalebenen-Interaktionen: <code>Received signals</code>, <code>Received data elements</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>PduR</code> signalisiert den Empfang an <code>Com</code> via <code>COM_RxIndication()</code>.\n</li><li><code>Com</code> ruft den Callout <code>IPDU_E2ECheck_21(RxPduId, IPduInfo)</code> auf.\n</li><li>Im Callout erfolgt einmalig beim Hochlauf (<code>[One time at startup]</code>) die Initialisierung von Konfigurations- und Zustandsstrukturen (<code>Hardcoded initialization of config/state structures</code>).\n</li><li><code>State.NewDataAvailable</code> wird auf <code>TRUE</code> gesetzt.\n</li><li>Der Callout ruft <code>E2E_P01Check(&amp;Settings, &amp;State, IPduInfo-&gt;SduDataPtr)</code> im Modul <code>E2E</code> auf.\n</li><li><code>E2E</code> führt die Prüfalgorithmen aus (<code>Execute check algorithms</code>) und liefert <code>Updated State</code> zurück.\n</li><li>Der Callout ermittelt das Prüfergebnis über <code>ret = ((State.Status == E2E_P01STATUS_OK) || (State.Status == E2E_P01STATUS_OK))</code> und gibt <code>ret</code> an <code>Com</code> zurück.\n</li><li>Bei <code>ret == FALSE</code> bricht <code>Com</code> die Weiterverarbeitung der I-PDU ab (<code>[ret == FALSE]:exit processing of I-PDU</code>).\n</li><li>Bei erfolgreicher Validierung extrahiert <code>Com</code> die Signale aus I-PDU 21 unter Berücksichtigung erforderlicher Konvertierungen (z. B. Endianness) (<code>Create signals out of I-PDU 21, do necessary conversions e.g. endiannes</code>).\n</li><li><code>Com</code> übergibt <code>Received signals</code> an die <code>Rte</code>.\n</li><li><code>Rte</code> leitet <code>Received data elements</code> an die <code>SWC</code> weiter.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als Integrations- und Implementierungsbeispiel für den E2E-Schutz über COM-Callouts auf Empfängerseite (Profil 1). Die Prüfung der I-PDU erfolgt vor dem Signalentpacken im COM-Stack. Schlägt die E2E-Validierung fehl (<code>ret == FALSE</code>), verwirft das COM-Modul die PDU, sodass keine fehlerhaften oder korrumpierten Signale an Rte und SWC propagiert werden. Die boolesche Auswertung <code>State.Status == E2E_P01STATUS_OK</code> steuert den Kontrollfluss direkt.</p>"}], "trans": [{"from": "FIG-839bb8def956e293", "to": "FIG-33f42cfe9c466859", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>COM Callout Benennung</strong>: Lebenslinie von <code>COM Callout IPDU_Protect_21</code> umbenannt in <code>COM Callout IPDU_E2ECheck_21</code>.\n</li><li><strong>Callout-Aufruf</strong>: Methodenaufruf von <code>IPDU_Check_21(id, ipduData)</code> geändert zu <code>IPDU_E2ECheck_21(RxPduId, IPduInfo)</code>.\n</li><li><strong>E2E-Check-Aufruf</strong>: Parameter für die Nutzdaten in <code>E2E_P01Check</code> von <code>&amp;ipduData</code> auf <code>IPduInfo-&gt;SduDataPtr</code> geändert.\n</li></ul>"}]};
